```python
def is_connected(n, edges):
    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v)  # Bug here!
    visited = set()
    def dfs(curr):
        visited.add(curr)
        for nbr in graph[curr]:
            if nbr not in visited:
                dfs(nbr)
    dfs(0)
    return len(visited) == n
```
